/// <summary>
/// MPJ_33690_PurchaseOrderChangeService Purchase Order service Contract
/// </summary>
[DataContractAttribute('purchaseOrderLines')]
class METPurchaseOrderServiceLinesContract implements SysOperationValidatable
{
    TradeLineNumber                 lineNumber;
    PdsCWInventQty                  cwQuantity;
    InventQty                       purchaseQty;
    PurchLineDlvDate                confirmedDeliveryDate;
    string20                        lineAction;


}

Method.Source:
    [DataMemberAttribute('LineNumber')]
    public TradeLineNumber parmLineNumber(TradeLineNumber  _lineNumber = lineNumber)
    {
        lineNumber = _lineNumber;

        return lineNumber;
    }

    [DataMemberAttribute('OrderedCatchWeightQuantity')]
    public PdsCWInventQty parmCWQuantity(PdsCWInventQty  _cwQuantity = cwQuantity)
    {
        cwQuantity = _cwQuantity;

        return cwQuantity;
    }

    [DataMemberAttribute('OrderedPurchaseQuantity')]
    public InventQty parmPurchaseQty(InventQty  _purchaseQty = purchaseQty)
    {
        purchaseQty = _purchaseQty;

        return purchaseQty;
    }

    /// <summary>
    /// Gets or sets the <c>confirmedDeliveryDate</c> parameter.
    /// </summary>
    /// <param name = "_confirmedDeliveryDate">The value to set.</param>
    /// <returns>The value of the <c>confirmedDeliveryDate</c> parameter.</returns>
    [DataMemberAttribute('ConfirmedLineDeliveryDate')]
    public PurchLineDlvDate parmConfirmedDeliveryDate(PurchLineDlvDate  _confirmedDeliveryDate = confirmedDeliveryDate)
    {
        confirmedDeliveryDate = _confirmedDeliveryDate;

        return confirmedDeliveryDate;
    }

    /// <summary>
    /// Gets or sets the <c>metPOEDIFAMsg</c> parameter.
    /// </summary>
    /// <param name = "_metPOEDIFAMsg">The value to set.</param>
    /// <returns>The value of the <c>metPOEDIFAMsg</c> parameter.</returns>
    [DataMemberAttribute('LineAction')]
    public string20 parmLineAction(string20  _lineAction = lineAction)
    {
        lineAction = _lineAction;

        return lineAction;
    }

public boolean validate()
{
    boolean isValid = true;
    if (lineAction != METConstants::LineChanged || lineAction != METConstants::LineRejected )
    {
        isValid = checkFailed(strFmt("@MET:POLineActionErr"));
    }
    return isValid;
}
